INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (446, 1, 'blkid 역할', 'blkid 는 무엇을 알려 줄까요?', '내용 종류와 속성이에요.', NULL, NULL, '[]', 'choice', '["블록 장치의 읽기·쓰기 속도", "블록 장치의 사용량과 남은 공간", "내용 유형과 NAME=value 속성", "블록 장치가 연결된 물리 경로"]', 2, 'blkid 문서는 블록 장치의 내용 유형과 메타데이터의 NAME=value 속성을 보여 주며, 장치 정보에는 lsblk 를 권한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 2, '캐시 기본 위치', 'blkid 의 **기본 캐시 파일** 은 어디일까요?', '/run 아래예요.', NULL, NULL, '[]', 'choice', '["/etc/blkid/cache.db", "/run/blkid/blkid.tab", "/var/lib/blkid/cache", "/proc/blkid"]', 1, '문서는 기본 캐시 파일이 /run/blkid/blkid.tab 이고 /run 이 없는 시스템에서는 /etc/blkid.tab 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 3, '-p 옵션', '`blkid -p` 는 무엇을 할까요?', '캐시를 건너뛰어요.', NULL, NULL, '[]', 'choice', '["캐시를 건너뛰고 저수준으로 직접 조사한다", "캐시를 새로 만들어 저장한다", "결과를 파일로 내보낸다", "장치를 읽기 전용으로 열기만 한다"]', 0, '문서는 -p 가 저수준 superblock 조사 모드로 바꿔 캐시를 건너뛴다고 설명하며, 이때 파티션 테이블 정보(PTTYPE, PART_ENTRY_*)도 나온다고 합니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 4, '-g 옵션', '`blkid -g` 는 무엇을 할까요?', '정리예요.', NULL, NULL, '[]', 'choice', '["캐시를 비우고 다시 만든다", "장치를 그룹으로 묶는다", "결과를 한 줄로 합친다", "더는 없는 장치를 캐시에서 정리한다"]', 3, '문서는 -g 가 가비지 컬렉션으로 더는 존재하지 않는 장치를 캐시에서 제거한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 5, '-o export', '`blkid -o export` 의 출력은 어떤 모양일까요?', '환경 변수예요.', NULL, NULL, '[]', 'choice', '["장치 이름만 출력한다", "태그의 값만 출력한다", "key=value 쌍", "사람이 보기 좋은 표 형태"]', 2, '문서는 export 형식이 환경에 가져오기 쉬운 key=value 쌍이라고 설명합니다. value 는 값만, device 는 장치 이름만 출력합니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 6, '-o 기본', '`-o` 를 주지 않으면 출력 형식은 무엇일까요?', '전부 보여 줘요.', NULL, NULL, '[]', 'choice', '["value (태그 값만)", "full (모든 태그)", "device (장치 이름만)", "list (사용자 친화 표)"]', 1, '문서는 full 형식이 모든 태그를 출력하는 기본값이라고 설명합니다. list 는 lsblk 로 대체되어 폐기 예정입니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 7, '-s 옵션', '`blkid -s TYPE` 은 무엇을 할까요?', '태그를 골라요.', NULL, NULL, '[]', 'choice', '["지정한 태그만 보여 준다", "TYPE 이 같은 장치만 찾는다", "TYPE 을 바꾼다", "결과를 TYPE 순으로 정렬한다"]', 0, '문서는 -s 가 지정한 각 장치에서 일치하는 태그만 보여 준다고 설명합니다. 값으로 장치를 찾는 것은 -t 입니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 8, '종료 코드 2', 'blkid 종료 코드 `2` 는 무엇을 뜻할까요?', '못 찾았어요.', NULL, NULL, '[]', 'choice', '["사용법 오류가 났다", "조사 결과가 모호했다", "장치를 찾았고 정보를 얻었다", "토큰이나 장치를 못 찾았다"]', 3, '문서는 종료 코드 0 이 정보를 얻음, 2 가 토큰·장치를 찾지 못함, 4 가 사용법 오류, 8 이 저수준 조사 결과의 모호함이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 9, '종료 코드 8', 'blkid 종료 코드 `8` 은 언제 나올까요?', '-p 모드에서예요.', NULL, NULL, '[]', 'choice', '["지정한 토큰을 찾지 못했을 때", "사용법 오류가 났을 때", "-p 조사 결과가 모호할 때", "캐시 파일을 쓰지 못했을 때"]', 2, '문서는 저수준 조사 모드(-p)에서 모호한 결과가 감지되면 종료 코드 8 을 돌려준다고 설명합니다.', NULL, NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 10, '출력 형식', '환경 변수로 가져오기 쉬운 **key=value** 형식을 고르는 값입니다. 빈칸을 채우세요.', '"내보내기" 예요.', NULL, NULL, '[]', 'fill', '["export", "value", "device", "full"]', NULL, 'export 는 key=value 쌍을 출력합니다. value 는 값만, device 는 장치 이름만 냅니다.', '[0]', 'blkid -o {0} /dev/sdb1', NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 11, '토큰 검색', 'NAME=value 토큰으로 **장치를 찾는** 옵션입니다. 빈칸을 채우세요.', 'token 의 t 예요.', NULL, NULL, '[]', 'fill', '["-t", "-s", "-L", "-U"]', NULL, '-t/--match-token 은 NAME=value 토큰으로 장치를 찾습니다. -L 과 -U 는 레이블·UUID 값만 받습니다.', '[0]', 'blkid {0} LABEL=data', NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]'),
  (446, 12, 'blkid 점검', '장치 정보를 확인하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '캐시 → 저수준 → 정리 → 코드예요.', NULL, NULL, '[]', 'order', '["`blkid` 로 캐시 기반 정보를 본다", "정보가 의심스러우면 `-p` 로 저수준 조사를 한다", "`-g` 로 없어진 장치를 캐시에서 정리한다", "종료 코드로 결과를 판단한다"]', NULL, '문서의 캐시·-p·-g·종료 코드 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "blkid(8) man page", "url": "https://man7.org/linux/man-pages/man8/blkid.8.html"}]');
